t2 = {title: "Design ferdig", timestamp: "Uke 3", description: "Wireframes og designsystem godkjent", status: "done"}
t3 = {title: "Backend ferdig", timestamp: "Uke 5", description: "API og datamodell på plass", status: "done"}
